"""The story page below is invented; it reproduces the layout of a xenafan
part-1 story page (header block, first <hr>, part nav, author-listing link)."""
from fanfic_scraper.parse.schema import Part, Record
from fanfic_scraper.parse.xenafan_story import apply_story_header, parse_xenafan_story

URL = "https://xenafan.com/fiction/content5/lanternbard_exnihilo1.html"

PAGE = """<html><head>
<meta charset="windows-1252">
<title>Ex Nihilo, Part I</title>
<meta name="author" content="Lanternbard">
<meta name="description" content="short story">
</head><body>
<!-- generated by FrontPage --><center><b>Ex Nihilo</b><br>by Lanternbard</center>
<p>Disclaimer: Xena and Gabrielle belong to MCA/Universal.</p>
<p>Sequel to <a href="lanternbard_beginnings1.html">Beginnings</a>.
Violence warning. Feedback: lanternbard@example.com</p>
<hr>
<p>The story begins here and must not be in the header.</p>
<p><a href="lanternbard_exnihilo1.html">I</a> <a href="lanternbard_exnihilo2.html">II</a>
<a href="lanternbard_exnihilo8.html">VIII</a> <a href="../../index.html">Home</a></p>
<p><a href="../list/bardlistc.html#lanternbard">More by Lanternbard</a></p>
</body></html>""".encode("cp1252")


def test_header_text_stops_at_first_hr():
    header = parse_xenafan_story(PAGE, URL)
    assert header.disclaimer_text.splitlines()[0] == "Ex Nihilo"
    assert "Disclaimer: Xena and Gabrielle belong to MCA/Universal." in header.disclaimer_text
    assert "Sequel to Beginnings. Violence warning. Feedback: lanternbard@example.com" in header.disclaimer_text
    assert "story begins here" not in header.disclaimer_text
    assert "FrontPage" not in header.disclaimer_text
    assert header.author_emails == ["lanternbard@example.com"]


def test_meta_author_title_and_author_listing():
    header = parse_xenafan_story(PAGE, URL)
    assert header.meta_author == "Lanternbard"
    assert header.page_title == "Ex Nihilo, Part I"
    assert header.author_listing_url == "https://xenafan.com/fiction/list/bardlistc.html#lanternbard"


def test_nav_parts_are_same_directory_story_links():
    header = parse_xenafan_story(PAGE, URL)
    urls = [p.url.rsplit("/", 1)[1] for p in header.nav_parts]
    assert urls == ["lanternbard_exnihilo1.html", "lanternbard_exnihilo2.html", "lanternbard_exnihilo8.html"]
    assert "index.html" not in urls


def test_missing_hr_is_reported_not_guessed():
    header = parse_xenafan_story(b"<html><body><p>Just text</p></body></html>", URL)
    assert header.disclaimer_text is None
    assert header.warnings


def test_apply_records_part_count_discrepancy_in_notes():
    record = Record(
        source_site="xenafan", source_id="content5/lanternbard_exnihilo1.html", title="Ex Nihilo",
        authors=["Lanternbard"], parts=[Part("Part I", "content5/lanternbard_exnihilo1.html")],
        notes="sequel to Beginnings", fetched_from=["https://xenafan.com/fiction/titles.html"],
    )
    header = parse_xenafan_story(PAGE, URL)
    apply_story_header(record, header, URL)
    assert record.disclaimer_text == header.disclaimer_text
    assert record.author_page_url == header.author_listing_url
    assert record.fetched_from[-1] == URL
    assert record.notes.startswith("sequel to Beginnings; story page nav lists")
